273	                    val1 *= channel_scales_inv(i + (jj + 1) / pack_num * channel_stride);
274	                    val2 *= channel_scales_inv(i + (jj + 2) / pack_num * channel_stride);
275	                    val3 *= channel_scales_inv(i + (jj + 3) / pack_num * channel_stride);
276	
277	                    // Round and clamp the values
278	                    val0 = fminf(fmaxf(roundf(val0), 0.0f), max_val);
279	                    val1 = fminf(fmaxf(roundf(val1), 0.0f), max_val);
280	                    val2 = fminf(fmaxf(roundf(val2), 0.0f), max_val);
281	                    val3 = fminf(fmaxf(roundf(val3), 0.0f), max_val);
282	
283	                    // Pack the 4 quantized values into a 16-bit integer
284	                    uint16_t packed = 0;
285	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val3)) & 0xF);
286	                    packed <<= 4;
287	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val2)) & 0xF);
288	                    packed <<= 4;
289	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val1)) & 0xF);
290	                    packed <<= 4;
291	                    packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val0)) & 0xF);
292	
293	                    // Store the packed value
294	                    dst(i, jj / 4, k) = packed;
295	                }
296	            }
297	        }
298	
299	    }
