315	CUTE_DEVICE
316	void quad_allreduce_g(TensorParamsG0 &dst, Tensor1 &src, Operator &op, int k, int num_params) {
317	    CUTE_UNROLL
318	    for (int i = k * num_params; i < (k + 1) * num_params; i++) {
319	
320	        // Calculate which group of 4 this thread belongs to
321	        const int group_id = threadIdx.x / 4;
322	        const int group_base = group_id * 4;
323	        
324	        // Start with the value from the first thread in our group
325	        auto val = __shfl_sync(uint32_t(-1), src(i), group_base);
326	        
327	        // Reduce with the other 3 threads in our group
328	        #pragma unroll
329	        for (int offset = 1; offset < 4; offset++) {
330	            val = op(val, __shfl_sync(uint32_t(-1), src(i), group_base + offset));
331	        }
332	        
333	        // Broadcast the final result back to all threads in the group
334	        dst(i) = val;
335	
336	    }
337	}
